"""Render a deterministic markdown measure dictionary from metric contracts."""

from __future__ import annotations

from .contract import Metric
from .engine import build_sql


def _cell(text: str) -> str:
    """Make text safe for a single markdown table cell."""
    return " ".join(text.split()).replace("|", "\\|")


def _code_list(items: tuple[str, ...]) -> str:
    return ", ".join(f"`{i}`" for i in items) if items else "_none_"


def render(metrics: list[Metric]) -> str:
    out = [
        "# Measure Dictionary",
        "",
        "Generated by metric-contract (`mc docs`) from the YAML contracts. "
        "Do not edit by hand: change the contract and regenerate.",
        "",
        f"Metrics: {len(metrics)}",
        "",
        "## Summary",
        "",
        "| Name | Label | Owner | Table | Tests |",
        "|---|---|---|---|---|",
    ]
    for m in metrics:
        tests = ", ".join(m.tests.describe()) or "-"
        out.append(
            f"| [`{m.name}`](#{m.name}) | {_cell(m.label)} | {_cell(m.owner)} "
            f"| `{m.table}` | {_cell(tests)} |"
        )
    out += ["", "## Metrics", ""]
    for m in metrics:
        out += [
            f"### {m.name}",
            "",
            f"**{m.label}** (`{m.name}`)",
            "",
            m.description.strip(),
            "",
            f"- **Owner:** {m.owner}",
            f"- **Table:** `{m.table}`",
            f"- **Expression:** `{m.sql}`",
            f"- **Grain:** {_code_list(m.grain)}",
            f"- **Dimensions:** {_code_list(m.dimensions)}",
            f"- **Filters:** {_code_list(m.filters)}",
            f"- **Tests:** {', '.join(m.tests.describe()) or '_none_'}",
            f"- **Source contract:** `{m.source}`",
            "",
            "Executed as:",
            "",
            "```sql",
            build_sql(m),
            "```",
            "",
        ]
    return "\n".join(out).rstrip("\n") + "\n"
